// Generate the MoonBit plan table and its tests from data/numbering-plans.json.
//
//   node scripts/gen-metadata.mjs           # write the generated files
//   node scripts/gen-metadata.mjs --check   # fail if they are out of date
//
// The two generated artifacts are the single source of plan data the library
// compiles: every region, every type pattern and every published example number
// comes from here. `--check` is what the CI job runs, so a hand edit to the
// generated table (or a stale table after a data refresh) fails the build
// instead of drifting silently.
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const DATA = path.join(ROOT, "data", "numbering-plans.json");
const TABLE = path.join(ROOT, "plan_data.mbt");
const EXAMPLES = path.join(ROOT, "plan_examples_test.mbt");
const INVARIANTS = path.join(ROOT, "plan_data_wbtest.mbt");

const check = process.argv.includes("--check");

const TYPES = {
  f: "FixedLine",
  m: "Mobile",
  t: "TollFree",
  p: "PremiumRate",
  s: "SharedCost",
  v: "Voip",
  r: "PersonalNumber",
  u: "Uan",
  g: "Pager",
  o: "Voicemail",
};

const q = (s) => '"' + s.replace(/\\/g, "\\\\").replace(/"/g, '\\"') + '"';
const ints = (a) => "[" + a.join(", ") + "]";
const strs = (a) => "[" + a.map(q).join(", ") + "]";

function table(doc) {
  const out = [];
  out.push("// Numbering-plan data, generated from data/numbering-plans.json.");
  out.push("//");
  out.push("// Do not edit this file: run `node scripts/gen-metadata.mjs` instead.");
  out.push(`// Source: ${doc.meta.source}`);
  out.push(`// License: ${doc.meta.license} · retrieved ${doc.meta.retrieved} · sha256 ${doc.meta.sha256}`);
  out.push(`// Regions: ${doc.meta.regions} · patterns: ${doc.meta.patterns}`);
  out.push("");
  out.push("///|");
  out.push("/// The whole table, sorted by region code.");
  out.push("let regions : Array[Region] = [");
  for (const r of doc.regions) {
    out.push("  plan_row(");
    out.push(
      `    ${q(r.code)}, ${q(r.name)}, ${r.calling_code}, ${q(r.idd)}, ${q(r.national_prefix)}, ${q(r.prefix_parsing ?? "")}, ${q(r.leading_digits ?? "")}, ${r.primary},`,
    );
    out.push(`    ${q(r.general)},`);
    out.push("    [");
    for (const t of r.types) {
      out.push(
        `      plan_type(${TYPES[t.kind]}, ${q(t.pattern)}, ${ints(t.national)}, ${ints(t.local_only ?? [])}),`,
      );
    }
    out.push("    ],");
    out.push("    [");
    for (const f of r.formats ?? []) {
      out.push(
        `      plan_format(${q(f.pattern)}, ${strs(f.leading)}, ${q(f.format)}, ${q(f.intl ?? "")}, ${q(f.prefix_rule ?? "")}),`,
      );
    }
    out.push("    ],");
    out.push("  ),");
  }
  out.push("]");
  out.push("");
  return out.join("\n");
}

// A JavaScript mirror of the resolution order documented in valid.mbt, used to
// pin the expected region of every published example: patterns first (primary
// region winning a tie), then the published length as a fallback. For +1 the
// NANP structural rule runs first.
const matches = (pattern, text) => new RegExp("^(?:" + pattern + ")$").test(text);

function nanpPossible(nn) {
  if (!/^\d{10}$/.test(nn)) return false;
  if (!/[2-9]/.test(nn[0])) return false;
  if (nn[1] === "1" && nn[2] === "1") return false;
  return /[2-9]/.test(nn[3]);
}

function expectedRegion(doc, number, callingCode) {
  if (callingCode === 1 && !nanpPossible(number)) return null;
  const candidates = doc.regions.filter((r) => r.calling_code === callingCode);
  const ordered = [...candidates].sort((a, b) => Number(b.primary) - Number(a.primary));
  for (const r of ordered) {
    if (r.types.some((t) => matches(t.pattern, number))) return r.code;
  }
  for (const r of ordered) {
    if (r.types.some((t) => t.national.includes(number.length))) return r.code;
  }
  return null;
}

function examplesTest(doc) {
  const out = [];
  out.push("// Golden tests for every published example number.");
  out.push("//");
  out.push("// Generated from data/numbering-plans.json by scripts/gen-metadata.mjs.");
  out.push(
    "// Each block proves one region end to end: the example is accepted by the",
  );
  out.push(
    "// region's own rule, reports a plausible number type, and resolves to the",
  );
  out.push("// region the resolution order in region.mbt picks.");
  const withExamples = doc.regions.filter((r) => r.types.some((t) => t.example));
  for (const r of withExamples) {
    out.push("");
    out.push(`///|`);
    out.push(`test "plan examples: ${r.code} ${r.name.replace(/"/g, "'")}" {`);
    for (const t of r.types) {
      if (!t.example) continue;
      const kind = TYPES[t.kind];
      const pn = `@dialnumber.PhoneNumber::new(${r.calling_code}, "${t.example}")`;
      const region = expectedRegion(doc, t.example, r.calling_code);
      out.push(`  assert_true(@dialnumber.is_valid_in_region(${pn}, "${r.code}"))`);
      if (region === null) {
        // A local-only published example (the NANP's seven-digit UAN) is not a
        // full national number, so it has no region and no type of its own.
        out.push(`  assert_eq(@dialnumber.region_of_number(${pn}), None)`);
        out.push(`  assert_eq(@dialnumber.number_type(${pn}), None)`);
        continue;
      }
      out.push(`  assert_eq(@dialnumber.region_of_number(${pn}), Some("${region}"))`);
      if (kind === "FixedLine" || kind === "Mobile") {
        out.push(`  assert_true(matches_kind(@dialnumber.number_type(${pn}), ${kind}))`);
        // The national rendering must read back as the same number in the same
        // region: that is what "as dialled in the country" has to mean. Plans
        // that rewrite the number while parsing (see dial_transform in the
        // data) are skipped, because this library does not implement that
        // transformation and would be testing a known gap.
        if (!r.dial_transform) {
          out.push(`  match @dialnumber.format_national(${pn}, "${r.code}") {`);
          out.push(`    Some(written) => assert_eq(@dialnumber.parse(written, "${r.code}"), Some(${pn}))`);
          out.push("    None => assert_true(false)");
          out.push("  }");
        }
      } else {
        out.push(`  assert_eq(@dialnumber.number_type(${pn}), Some(${kind}))`);
      }
    }
    out.push("}");
  }
  out.push("");
  out.push("///|");
  out.push(
    "/// Fixed-line and mobile examples may be reported as either of the two, or",
  );
  out.push("/// as the shared type, depending on how the plan's rules overlap.");
  out.push(
    "fn matches_kind(actual : @dialnumber.NumberType?, expected : @dialnumber.NumberType) -> Bool {",
  );
  out.push("  match actual {");
  out.push(
    "    Some(@dialnumber.FixedLineOrMobile) => expected == @dialnumber.FixedLine || expected == @dialnumber.Mobile",
  );
  out.push("    Some(t) => t == expected");
  out.push("    None => false");
  out.push("  }");
  out.push("}");
  out.push("");
  return out.join("\n");
}

function invariantsTest(doc) {
  const withTypes = doc.regions.reduce((n, r) => n + r.types.length, 0);
  const out = [];
  out.push("// Whitebox checks on the generated table itself.");
  out.push("//");
  out.push("// These hold the data pipeline to its promises: every rule in the table");
  out.push("// must be in the engine's grammar, every region must be described, and the");
  out.push("// coverage counts must match the published metadata.");
  out.push("");
  out.push("///|");
  out.push('test "the table covers the published metadata" {');
  out.push(`  assert_eq(regions.length(), ${doc.regions.length})`);
  out.push(`  assert_eq(count_plan_types(), ${withTypes})`);
  out.push("}");
  out.push("");
  out.push("///|");
  out.push('test "every published rule is in the supported grammar" {');
  out.push("  for r in regions {");
  out.push("    assert_true(pattern_well_formed(r.general))");
  out.push("    for t in r.types {");
  out.push("      assert_true(pattern_well_formed(t.pattern))");
  out.push("    }");
  out.push("  }");
  out.push("}");
  out.push("");
  out.push("///|");
  out.push('test "every region is named and reachable" {');
  out.push("  for r in regions {");
  out.push("    assert_true(r.name.length() > 0)");
  out.push("    match find_region(r.code) {");
  out.push("      Some(found) => assert_eq(found.code, r.code)");
  out.push("      None => assert_true(false)");
  out.push("    }");
  out.push("    assert_true(r.types.length() > 0)");
  out.push("  }");
  out.push("}");
  out.push("");
  out.push("///|");
  out.push('test "the NANP is complete" {');
  out.push("  let nanp : Array[String] = []");
  out.push("  for r in regions {");
  out.push("    if r.calling_code == 1 {");
  out.push('      nanp.push(r.code)');
  out.push("    }");
  out.push("  }");
  out.push(`  assert_eq(nanp.length(), ${doc.regions.filter((r) => r.calling_code === 1).length})`);
  out.push('  assert_true(nanp.contains("US"))');
  out.push('  assert_true(nanp.contains("CA"))');
  out.push('  assert_true(nanp.contains("PR"))');
  out.push("}");
  out.push("");
  out.push("///|");
  out.push("fn count_plan_types() -> Int {");
  out.push("  let mut n = 0");
  out.push("  for r in regions {");
  out.push("    n = n + r.types.length()");
  out.push("  }");
  out.push("  n");
  out.push("}");
  out.push("");
  return out.join("\n");
}

const doc = JSON.parse(fs.readFileSync(DATA, "utf8"));
const files = [
  [TABLE, table(doc)],
  [EXAMPLES, examplesTest(doc)],
  [INVARIANTS, invariantsTest(doc)],
];

let drift = 0;
for (const [file, content] of files) {
  const current = fs.existsSync(file) ? fs.readFileSync(file, "utf8") : "";
  if (current === content) continue;
  if (check) {
    console.error(`out of date: ${path.relative(ROOT, file)}`);
    drift++;
  } else {
    fs.writeFileSync(file, content);
    console.log(`wrote ${path.relative(ROOT, file)} (${content.length} bytes)`);
  }
}
if (check) {
  if (drift > 0) process.exit(1);
  console.log("generated files are up to date");
}
